const staticData = $getWorkflowStaticData('global');
const telefono = $('Normalizar Update').first().json.message.from.id;
const textoRaw = ($json.message.text || '').trim();
const listaRaw = staticData[telefono + '_del_lista'];
const TTL_MS = 15 * 60 * 1000; // pendientes expiran a los 15 min (QA SD-01)
const guardado = listaRaw ? JSON.parse(listaRaw) : null;
// Formato {ts, lista}. Listas antiguas (array sin ts) o vencidas se descartan: sus
// row_number pueden apuntar ya a otras filas si la hoja cambió.
const lista = guardado && !Array.isArray(guardado) && Date.now() - (guardado.ts || 0) <= TTL_MS
  ? (guardado.lista || [])
  : [];

function normalizar(s) {
  return (s || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}
const textoNorm = normalizar(textoRaw);
const esNumerico = /^\s*\d+(\s*,\s*\d+)*\s*$/.test(textoRaw);
const esSoloTodos = /^\s*todos\s*$/.test(textoNorm);
const tieneVerboEliminar = /\b(elimina|borra|quita|remueve)/.test(textoNorm);
const contieneTodos = esSoloTodos || (/\btodos\b/.test(textoNorm) && tieneVerboEliminar);
const pareceSeleccion = esNumerico || contieneTodos;

if (lista.length === 0 || !pareceSeleccion) {
  return [{ json: { ...$json, esSeleccion: false } }];
}

let numerosPedidos;
if (contieneTodos) {
  numerosPedidos = lista.map(c => c.numero);
} else {
  numerosPedidos = textoRaw.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
}

const encontrados = [];
const noEncontrados = [];
for (const n of numerosPedidos) {
  const c = lista.find(x => x.numero === n);
  if (c) encontrados.push(c); else noEncontrados.push(n);
}

return [{ json: { ...$json, esSeleccion: true, encontrados, noEncontrados, count: encontrados.length } }];

const items = $('Recuperar y Detectar Acción').first().json.items || [];
// Gasto sin productos (texto/voz): marcador para saltar Append Items sin cortar el flujo.
if (items.length === 0) return [{ json: { _sinItems: true } }];
return items.map(item => ({ json: item }));

