// Guardia QA (SF-02): nunca escribir un gasto incompleto en la hoja.
const d = $('Recuperar y Detectar Acción').first().json;
const vacio = v => v === undefined || v === null || String(v).trim() === '';
const faltantes = ['id', 'fecha', 'establecimiento', 'monto', 'moneda'].filter(k => vacio(d[k]));
const itemsMalos = (d.items || []).filter(i => vacio(i.nombre_producto) || !Number.isFinite(Number(i.precio_unitario)));
if (faltantes.length || itemsMalos.length) {
  throw new Error(`Gasto incompleto. Faltan: ${faltantes.join(', ') || '-'}; items inválidos: ${itemsMalos.length}`);
}
return $input.all();
